_GaragePage.garagePage.addCarBtn.click();
_GaragePage.garagePage.modalTitle.should('be.visible').and('have.text', 'Add a car');
_GaragePage.garagePage.closeIcon.should('be.visible');
_GaragePage.garagePage.cancelBtn.should('be.visible');
_GaragePage.garagePage.submitAddCarBtn.should('be.disabled');
// Обов'язково закриваємо модалку, щоб очистити стан для наступного тесту
_GaragePage.garagePage.cancelBtn.click();

_GaragePage.garagePage.addCarBtn.click();
_GaragePage.garagePage.mileageInput.focus().blur();
// Перевіряємо помилку через метод getErrorMessage, який ми створили в Page Object
_GaragePage.garagePage.mileageError.should('be.visible').and('have.text', 'Mileage cost required');
_GaragePage.garagePage.mileageInput.should('have.css', 'border-color').and('eq', _GaragePage.garagePage.redColor);
_GaragePage.garagePage.submitAddCarBtn.should('be.disabled');
// Обов'язково закриваємо модалку після перевірки помилки
_GaragePage.garagePage.cancelBtn.click();

_GaragePage.garagePage.addCarBtn.click();
const brand = 'BMW';
const model = 'X5';
const mileage = '150';
// Заповнюємо форму за допомогою методу з нашого Page Object
_GaragePage.garagePage.fillCarForm(brand, model, mileage);
// Кликаємо Add та перевіряємо результат
_GaragePage.garagePage.submitAddCarBtn.should('not.be.disabled').click();
_GaragePage.garagePage.modalTitle.should('not.exist');
_GaragePage.garagePage.carItemName.first().should('be.visible').and('contain', `${brand} ${model}`);
